            --glass-bg: rgba(255, 255, 255, 0.4);
            --glass-border: rgba(255, 255, 255, 0.6);
            --glass-shadow: rgba(30, 41, 59, 0.15);
            --text-dark: #1e293b;
            --text-light: #64748b;
            --accent-color: #94a3b8;
