    <script>
        // 1. 界面平滑切换逻辑
        const panelProfile = document.getElementById('panelProfile');
        const panelStories = document.getElementById('panelStories');
        const navToStoriesBtn = document.getElementById('navToStories');
        const navToProfileBtn = document.getElementById('navToProfile');

        // 前往开场白界面
        navToStoriesBtn.addEventListener('click', () => {
            panelProfile.classList.remove('active');
            panelStories.classList.add('active');
        });

        // 返回人物主页
        navToProfileBtn.addEventListener('click', () => {
            panelStories.classList.remove('active');
            panelProfile.classList.add('active');
        });

        // 2. 模态框逻辑
        const openModalBtn = document.getElementById('openModalBtn');
        const closeModalBtn = document.getElementById('closeModalBtn');
        const modalOverlay = document.getElementById('modalOverlay');

        openModalBtn.addEventListener('click', () => modalOverlay.classList.add('active'));
        closeModalBtn.addEventListener('click', () => modalOverlay.classList.remove('active'));

        // 3. 气泡交互逻辑 (5句台词)
        const avatarBtn = document.getElementById('avatarBtn');
        const chatBubble = document.getElementById('chatBubble');

        const lines = [
            "嗯……你回来了。",
            "别一直盯着我看……好麻烦。",
            "啊……今天不想出门。",
            "画稿还没画完……过来陪我。",
            "果然……还是待在你身边最好。"
        ];

        let bubbleTimeout;

        avatarBtn.addEventListener('click', () => {
            // 随机选取一句
            const randomLine = lines[Math.floor(Math.random() * lines.length)];
            chatBubble.innerText = randomLine;

            // 显示气泡
            chatBubble.classList.add('show');

            // 清除之前的定时器
            if(bubbleTimeout) clearTimeout(bubbleTimeout);

            // 3秒后隐藏
            bubbleTimeout = setTimeout(() => {
                chatBubble.classList.remove('show');
            }, 3000);
        });

        // 4. 动态开场白加载逻辑
        async function loadOpenings() {
            const container = document.getElementById('storyListContainer');
            if (!container) return;

            if (typeof getChatMessages !== 'function') {
                container.innerHTML = '<div style="padding:40px 20px;text-align:center;color:#64748b;font-size:0.9rem;line-height:1.6;">检测不到酒馆助手环境，<br>请确保酒馆助手插件已开启。</div>';
                return;
            }

            try {
                const messages = await getChatMessages("0", { include_swipe: true });

                if (!messages || messages.length === 0 || !messages[0].swipes || messages[0].swipes.length <= 1) {
                    container.innerHTML = '<div style="padding:40px 20px;text-align:center;color:#64748b;font-size:0.9rem;line-height:1.6;">暂无其他开场白记录。<br>请在角色卡设置中添加。</div>';
                    return;
                }

                const swipes = messages[0].swipes;

                // 从1开始，跳过0（主页本身）
                for (let i = 1; i < swipes.length; i++) {
                    const content = swipes[i];
                    let title = `记忆片段 0${i}`;
                    let description = "点击载入这段专属剧情...";

                    const titleMatch = content.match(/<!--\s*title:\s*(.*?)\s*-->/s);
                    if (titleMatch) title = titleMatch[1].trim();

                    const descMatch = content.match(/<!--\s*desc:\s*(.*?)\s*-->/s);
                    if (descMatch) description = descMatch[1].trim();

                    const item = document.createElement('div');
                    item.className = 'story-item';
                    item.innerHTML = `
                        <div class="story-title">${title}</div>
                        <div class="story-desc">${description}</div>
                    `;

                    item.addEventListener('click', (event) => switchToOpening(i, event));
                    container.appendChild(item);
                }

            } catch (error) {
                console.error('加载开场白失败:', error);
                container.innerHTML = '<div style="padding:40px 20px;text-align:center;color:#ef4444;font-size:0.9rem;line-height:1.6;">加载数据出错，请查阅控制台。</div>';
            }
        }

        async function switchToOpening(swipeId, event) {
            const card = event ? event.currentTarget : null;
            if (card) {
                 card.style.opacity = '0.5';
                 card.style.pointerEvents = 'none';
            }

            try {
                await setChatMessages([{message_id: 0, swipe_id: swipeId}]);
            } catch (error) {
                console.error('切换开场白失败:', error);
                if(card){
                    card.style.opacity = '1';
                    card.style.pointerEvents = 'auto';
                }
            }
        }

        // 页面加载完毕后执行开场白抓取
        window.addEventListener('load', loadOpenings);

    </script>
</body>
